import React from 'react';
import { NavLink } from 'react-router-dom';
import {
  LayoutDashboard,
  Users,
  MapPin,
  ClipboardCheck,
  Activity,
  Accessibility,
  GraduationCap,
  Apple,
  Megaphone,
  Calendar,
  Star,
  FileText,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react';
import './Layout.css';

const Sidebar = ({ isOpen, toggleSidebar }) => {
  const menuItems = [
    { path: '/dashboard', icon: LayoutDashboard, label: 'Dashboard' },
    { path: '/children', icon: Users, label: 'Children' },
    { path: '/outreach', icon: MapPin, label: 'Outreach Clinics' },
    { path: '/assessments', icon: ClipboardCheck, label: 'Assessments' },
    { path: '/therapy', icon: Activity, label: 'Therapy' },
    { path: '/devices', icon: Accessibility, label: 'Assistive Devices' },
    { path: '/training', icon: GraduationCap, label: 'Caregiver Training' },
    { path: '/nutrition', icon: Apple, label: 'Nutrition' },
    { path: '/community', icon: Megaphone, label: 'Community Outreach' },
    { path: '/meetings', icon: Calendar, label: 'Meetings' },
    { path: '/success-stories', icon: Star, label: 'Success Stories' },
    { path: '/reports', icon: FileText, label: 'Reports' },
  ];

  return (
    <div className={`sidebar ${!isOpen ? 'collapsed' : ''}`}>
      <div className="sidebar-header">
        <div className="sidebar-logo">
          <img className="sidebar-logo-image" src="/logo.svg" alt="BK logo" />
          {isOpen && (
            <div className="logo-text">
              <div className="logo-title">BK Initiative</div>
              <div className="logo-subtitle">M&E System</div>
            </div>
          )}
        </div>
        <button className="sidebar-toggle" onClick={toggleSidebar}>
          {isOpen ? <ChevronLeft size={18} /> : <ChevronRight size={18} />}
        </button>
      </div>

      <nav className="sidebar-nav">
        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            className={({ isActive }) => `nav-item ${isActive ? 'active' : ''}`}
          >
            <item.icon size={20} className="nav-icon" />
            {isOpen && <span className="nav-label">{item.label}</span>}
          </NavLink>
        ))}
      </nav>

      <div className="sidebar-footer">
        <div className="sidebar-version">{isOpen ? 'v1.0.0' : 'v1'}</div>
      </div>
    </div>
  );
};

export default Sidebar;
